      gl.bindTexture(gl.TEXTURE_2D,this.texture);gl.texImage2D(gl.TEXTURE_2D,0,gl.RGB,gl.RGB,gl.UNSIGNED_BYTE,upload);
      this.ready=gl.getError()===gl.NO_ERROR;this.canvas.dataset.surface=this.ready?'ready':'error';
